<?php
require_once __DIR__.'/app.php';require_permission('customers.history');
$customerId=value_int($_GET['id']??null);
$pageTitle='Khách hàng';
if($customerId){
 $st=db()->prepare("SELECT u.* FROM users u JOIN roles r ON r.id=u.role_id WHERE r.code='customer' AND u.id=?");$st->execute([$customerId]);$customer=$st->fetch();if(!$customer){http_response_code(404);exit('Không tìm thấy khách hàng.');}
 $st=db()->prepare('SELECT id,status,total_amount,created_at FROM orders WHERE user_id=? ORDER BY id DESC');$st->execute([$customerId]);$history=$st->fetchAll();
 $st=db()->prepare("SELECT COUNT(*) orders_count,COALESCE(SUM(CASE WHEN status='delivered' THEN total_amount ELSE 0 END),0) delivered_value FROM orders WHERE user_id=?");$st->execute([$customerId]);$stats=$st->fetch();
}else{$customers=db()->query("SELECT u.id,u.full_name,u.email,u.is_active,u.created_at,(SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) total_orders,(SELECT COALESCE(SUM(o.total_amount),0) FROM orders o WHERE o.user_id=u.id AND o.status='delivered') delivered_value FROM users u JOIN roles r ON r.id=u.role_id AND r.code='customer' ORDER BY u.id DESC LIMIT 200")->fetchAll();}
require __DIR__.'/partials/header.php'; ?>
<div class="page-head"><div><div class="eyebrow">CUSTOMER INSIGHTS</div><h1><?= $customerId?'Lịch sử: '.h($customer['full_name']):'Khách hàng của cửa hàng' ?></h1><p>Manager xem dữ liệu đơn của từng Customer, không truy cập được mật khẩu.</p></div><?php if($customerId): ?><a class="btn outline" href="customers.php">← Tất cả khách hàng</a><?php endif; ?></div>
<?php if($customerId): ?><div class="metric-grid two-metrics"><div class="metric-card"><span class="metric-label">Số đơn từng đặt</span><strong><?= (int)$stats['orders_count'] ?></strong></div><div class="metric-card"><span class="metric-label">Giá trị đơn đã giao</span><strong><?= money($stats['delivered_value']) ?></strong></div></div><section class="panel"><div class="panel-head"><h2>Đơn hàng của <?= h($customer['full_name']) ?></h2></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Ngày mua</th><th>Tổng</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($history as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= h($o['created_at']) ?></td><td><?= money($o['total_amount']) ?></td><td><span class="badge <?= h(status_class($o['status'])) ?>"><?= h(status_name($o['status'])) ?></span></td><td><a href="order_detail.php?id=<?= (int)$o['id'] ?>" class="btn outline btn-small">Chi tiết</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$history): ?><div class="empty-small">Khách này chưa đặt đơn nào.</div><?php endif; ?></section>
<?php else: ?><section class="panel"><div class="panel-head"><h2>Hồ sơ & lịch sử đặt hàng</h2></div><div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Email</th><th>Số đơn</th><th>Giá trị đã giao</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td><strong><?= h($customer['full_name']) ?></strong></td><td><?= h($customer['email']) ?></td><td><?= (int)$customer['total_orders'] ?></td><td><?= money($customer['delivered_value']) ?></td><td><span class="badge <?= $customer['is_active']?'green':'red' ?>"><?= $customer['is_active']?'Hoạt động':'Khóa' ?></span></td><td><a class="btn outline btn-small" href="customers.php?id=<?= (int)$customer['id'] ?>">Lịch sử →</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php require __DIR__.'/partials/footer.php'; ?>
